// ============================================================================
// File: tb_feature4_pipeline.v
// Module: tb_feature4_pipeline
// Description: Full 5-Stage Pipeline Integration Testbench for Feature 4 (IEEE 754 FPU)
// Verifies:
//   - Pipelined execution of FADD.S (5c), FMUL.S (4c), FSUB.S (5c), and FDIV.S (15c)
//   - RAW FP Data Forwarding: x3 generated by FADD.S is bypassed directly into FMUL.S!
//   - Hazard Unit interlock stall: freezes PC, IF/ID, and ID/EX while fpu_busy == 1
//   - Pipeline bubble insertion into EX/MEM during multi-cycle FPU holds
//   - Writeback of FP results into register file and retirement verification
//   - Standard 50 MHz core clock ($T_{clk} = 20\text{ ns}$)
// ============================================================================

`timescale 1ns/1ps

module tb_feature4_pipeline;

    reg clk;
    reg reset_n;

    // 50 MHz Clock (20 ns period: 10 ns high, 10 ns low)
    initial begin
        clk = 0;
        forever #10 clk = ~clk;
    end

    // Interconnects
    wire [31:0] imem_addr;
    wire [31:0] imem_rdata;
    wire [31:0] dmem_addr;
    wire [31:0] dmem_wdata;
    wire [3:0]  dmem_wstrb;
    wire        dmem_we;
    wire        dmem_re;
    wire [31:0] dmem_rdata;

    wire [31:0] pc_if, pc_id, pc_ex, pc_mem, pc_wb;
    wire        wb_reg_write;
    wire [4:0]  wb_dest_reg;
    wire [31:0] wb_data;
    wire        hazard_stall, hazard_flush_id, hazard_flush_ex;
    wire [1:0]  forward_a, forward_b;
    wire        mul_active, div_active, div_busy, fpu_active, fpu_busy;
    wire        exception;

    // Instruction Memory Model
    reg [31:0] test_imem [0:63];
    assign imem_rdata = test_imem[imem_addr[7:2]];

    // 5-Stage Core DUT
    pipeline_5stage dut (
        .clk             (clk),
        .reset_n         (reset_n),
        .stall_ext       (1'b0),
        .use_dsp_i       (1'b1),
        .imem_addr       (imem_addr),
        .imem_rdata      (imem_rdata),
        .dmem_addr       (dmem_addr),
        .dmem_wdata      (dmem_wdata),
        .dmem_wstrb      (dmem_wstrb),
        .dmem_we         (dmem_we),
        .dmem_re         (dmem_re),
        .dmem_rdata      (32'h0),
        .pc_if           (pc_if),
        .pc_id           (pc_id),
        .pc_ex           (pc_ex),
        .pc_mem          (pc_mem),
        .pc_wb           (pc_wb),
        .wb_reg_write    (wb_reg_write),
        .wb_dest_reg     (wb_dest_reg),
        .wb_data         (wb_data),
        .hazard_stall    (hazard_stall),
        .hazard_flush_id (hazard_flush_id),
        .hazard_flush_ex (hazard_flush_ex),
        .forward_a       (forward_a),
        .forward_b       (forward_b),
        .mul_active      (mul_active),
        .div_active      (div_active),
        .div_busy        (div_busy),
        .fpu_active      (fpu_active),
        .fpu_busy        (fpu_busy),
        .exception       (exception)
    );

    integer pass_count = 0;
    integer fail_count = 0;

    initial begin
        $display("============================================================================");
        $display("       STARTING TESTBENCH: tb_feature4_pipeline (RV32IMF Core)             ");
        $display("                 Clock Frequency: 50 MHz (Period: 20 ns)                   ");
        $display("============================================================================");

        // Clear memory
        begin : init_mem
            integer j;
            for (j = 0; j < 64; j = j + 1) test_imem[j] = 32'h0000_0013; // NOPs
        end

        // Load RISC-V RV32F instruction program:
        // PC 0x00: lui x1, 0x3FC00   -> x1 = 1.5 (0x3FC00000)
        test_imem[0] = 32'h3FC000B7;
        // PC 0x04: lui x2, 0x40200   -> x2 = 2.5 (0x40200000)
        test_imem[1] = 32'h40200137;
        // PC 0x08: lui x4, 0x40000   -> x4 = 2.0 (0x40000000)
        test_imem[2] = 32'h40000237;
        // PC 0x0C: lui x6, 0x40A00   -> x6 = 5.0 (0x40A00000)
        test_imem[3] = 32'h40A00337;
        // PC 0x10: lui x8, 0x41200   -> x8 = 10.0 (0x41200000)
        test_imem[4] = 32'h41200437;
        // PC 0x14: FADD.S x3, x1, x2 -> x3 = 1.5 + 2.5 = 4.0 (0x40800000) [5 cycles]
        test_imem[5] = 32'h002081D3;
        // PC 0x18: FMUL.S x5, x3, x4 -> x5 = 4.0 * 2.0 = 8.0 (0x41000000) [4 cycles, RAW x3 forwarded!]
        test_imem[6] = 32'h104182D3;
        // PC 0x1C: FSUB.S x7, x6, x2 -> x7 = 5.0 - 2.5 = 2.5 (0x40200000) [5 cycles]
        test_imem[7] = 32'h082303D3;
        // PC 0x20: FDIV.S x9, x8, x4 -> x9 = 10.0 / 2.0 = 5.0 (0x40A00000) [15 cycles]
        test_imem[8] = 32'h184404D3;
        // Trailing NOPs
        test_imem[9]  = 32'h00000013;
        test_imem[10] = 32'h00000013;
        test_imem[11] = 32'h00000013;
        test_imem[12] = 32'h00000013;
        test_imem[13] = 32'h00000013;

        reset_n = 0;
        #40;
        @(posedge clk);
        #1;
        reset_n = 1;

        // Monitor Writeback retirements
        $display("\n--- Pipelined Instruction Execution Trace ---");
    end

    // Verify Writebacks
    always @(posedge clk) begin
        if (reset_n && wb_reg_write && wb_dest_reg != 5'd0) begin
            $display("Time=%0t | WB: PC=0x%08h | Reg x%0d <= 0x%08h", $time, pc_wb, wb_dest_reg, wb_data);
            case (wb_dest_reg)
                5'd1: begin
                    if (wb_data === 32'h3FC00000) pass_count = pass_count + 1;
                    else begin $display("[FAIL] x1 exp 0x3FC00000 got 0x%08h", wb_data); fail_count = fail_count + 1; end
                end
                5'd2: begin
                    if (wb_data === 32'h40200000) pass_count = pass_count + 1;
                    else begin $display("[FAIL] x2 exp 0x40200000 got 0x%08h", wb_data); fail_count = fail_count + 1; end
                end
                5'd4: begin
                    if (wb_data === 32'h40000000) pass_count = pass_count + 1;
                    else begin $display("[FAIL] x4 exp 0x40000000 got 0x%08h", wb_data); fail_count = fail_count + 1; end
                end
                5'd6: begin
                    if (wb_data === 32'h40A00000) pass_count = pass_count + 1;
                    else begin $display("[FAIL] x6 exp 0x40A00000 got 0x%08h", wb_data); fail_count = fail_count + 1; end
                end
                5'd8: begin
                    if (wb_data === 32'h41200000) pass_count = pass_count + 1;
                    else begin $display("[FAIL] x8 exp 0x41200000 got 0x%08h", wb_data); fail_count = fail_count + 1; end
                end
                5'd3: begin // FADD.S result
                    if (wb_data === 32'h40800000) begin
                        $display("[PASS] FADD.S retired: x3 = 4.0 (0x40800000) correctly!");
                        pass_count = pass_count + 1;
                    end else begin
                        $display("[FAIL] FADD.S x3: exp 0x40800000 got 0x%08h", wb_data);
                        fail_count = fail_count + 1;
                    end
                end
                5'd5: begin // FMUL.S result with RAW forwarding!
                    if (wb_data === 32'h41000000) begin
                        $display("[PASS] FMUL.S retired: x5 = 8.0 (0x41000000) with RAW operand forwarding from x3!");
                        pass_count = pass_count + 1;
                    end else begin
                        $display("[FAIL] FMUL.S x5: exp 0x41000000 got 0x%08h", wb_data);
                        fail_count = fail_count + 1;
                    end
                end
                5'd7: begin // FSUB.S result
                    if (wb_data === 32'h40200000) begin
                        $display("[PASS] FSUB.S retired: x7 = 2.5 (0x40200000) correctly!");
                        pass_count = pass_count + 1;
                    end else begin
                        $display("[FAIL] FSUB.S x7: exp 0x40200000 got 0x%08h", wb_data);
                        fail_count = fail_count + 1;
                    end
                end
                5'd9: begin // FDIV.S result
                    if (wb_data === 32'h40A00000) begin
                        $display("[PASS] FDIV.S retired: x9 = 5.0 (0x40A00000) after 15-cycle stall interlock!");
                        pass_count = pass_count + 1;
                    end else begin
                        $display("[FAIL] FDIV.S x9: exp 0x40A00000 got 0x%08h", wb_data);
                        fail_count = fail_count + 1;
                    end
                end
            endcase
        end
    end

    // Finish simulation
    initial begin
        #2500;
        $display("\n============================================================================");
        $display("             TB_FEATURE4_PIPELINE VERIFICATION SUMMARY                      ");
        $display("============================================================================");
        $display(" Instructions Checked: %0d", pass_count + fail_count);
        $display(" Passed Retirements  : %0d", pass_count);
        $display(" Failed Retirements  : %0d", fail_count);
        if (fail_count == 0 && pass_count >= 9) begin
            $display(" STATUS: FULL PIPELINE INTEGRATION PASSED 100%% WITH FPU STALLS & FORWARDING!");
        end else begin
            $display(" STATUS: FAILED!");
        end
        $display("============================================================================\n");
        $finish;
    end

endmodule
